type ExpansionOptions = Partial<Pick<LoreItem,"description"|"why"|"zoneRadiusM"|"time"|"timeSlot"|"duration"|"price"|"vibe"|"accessibility"|"accent"|"distance"|"format"|"traits"|"schedule"|"hotspot"|"featured"|"image">>;
const expansionAccent:Record<LoreItem["category"],string> = { Outside:"#78cfe8", Move:"#ff9b72", Make:"#67c8ff", Listen:"#f6c766", Eat:"#ff7866", Learn:"#a890ff", Community:"#70daa0", "After dark":"#df9bd8" };
const expansionFormat:Record<LoreItem["category"],NonNullable<LoreItem["format"]>> = { Outside:"Adventure", Move:"Adventure", Make:"Class", Listen:"Live", Eat:"Food", Learn:"Culture", Community:"Meetup", "After dark":"Live" };

function mission(id:string,title:string,kicker:string,category:LoreItem["category"],neighborhood:string,venue:string,coordinates:[number,number],sourceName:string,sourceUrl:string,options:ExpansionOptions={}):LoreItem {
  return {
    id,title,kicker,category,neighborhood,venue,coordinates,
    description:options.description ?? `Use ${venue}'s official page to shape a small, specific plan around this part of the city.`,
    why:options.why ?? `${kicker} — a simple reason to trade an ordinary errand for a more local hour.`,
    zoneRadiusM:options.zoneRadiusM ?? 140,time:options.time ?? "Check current hours or calendar",timeSlot:options.timeSlot ?? "Now",duration:options.duration ?? 1.5,price:options.price ?? 0,
    vibe:options.vibe ?? ["solo","friends","social"],accessibility:options.accessibility ?? "Check the official visitor page for current access details",source:source(sourceName,sourceUrl),accent:options.accent ?? expansionAccent[category],distance:options.distance ?? "Varies",format:options.format ?? expansionFormat[category],traits:options.traits,schedule:options.schedule,hotspot:options.hotspot,featured:options.featured,image:options.image,
  };
}

